import{_ as t,o as d,c as o,ax as s}from"./chunks/framework.Buhf-QP1.js";const k=JSON.parse(`{"title":"SDK","description":"The sdk object passed to a widget's init(sdk) function — widget runtime, Connectors SDK (sdk.connectors) and Web SDK (sdk.web)","frontmatter":{"description":"The sdk object passed to a widget's init(sdk) function — widget runtime, Connectors SDK (sdk.connectors) and Web SDK (sdk.web)"},"headers":[],"relativePath":"sdk/index.md","filePath":"sdk/index.md"}`),n={name:"sdk/index.md"};function r(a,e,c,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/sdk.md for this page in Markdown format</div><h1 id="sdk" tabindex="-1">SDK <a class="header-anchor" href="#sdk" aria-label="Permalink to &quot;SDK&quot;">​</a></h1><p>The SDK is the <code>sdk</code> object the platform passes to your widget&#39;s <code>init(sdk)</code> function. It carries the widget runtime plus two clients, and nothing needs to be constructed or loaded. Choose the part you need:</p><table tabindex="0"><thead><tr><th>Part</th><th>Access</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Runtime</strong></td><td><code>sdk.getProps()</code>, <code>sdk.$()</code>, <code>sdk.on()</code></td><td>The widget&#39;s shadow root, props, events, and design tokens — see the <a href="/docs/sdk/runtime-reference.html">Widget Runtime Reference</a>.</td></tr><tr><td><strong>Connectors</strong></td><td><code>sdk.connectors</code></td><td>Call <a href="/docs/connectors/">connectors</a> from widget code to reach external APIs — see the <a href="/docs/sdk/connectors-sdk/overview.html">Connectors SDK</a>.</td></tr><tr><td><strong>Web</strong></td><td><code>sdk.web</code></td><td>Search content, users, and subscriptions on community pages — see the <a href="/docs/sdk/web-sdk/overview.html">Web SDK</a>.</td></tr></tbody></table><p>Scripts have no <code>init(sdk)</code> function and use <code>window.ChWebSdk</code> instead.</p><p>New to widgets? Start with <a href="/docs/custom-widgets/v2/build-first-widget.html">Your First Widget</a>. To call an external API from a widget, see <a href="/docs/connectors/calling-from-widgets.html">Calling from Widget Code</a>. For how the three parts relate, read <a href="/docs/sdk/concepts.html">SDK Concepts</a>.</p>',6)])])}const m=t(n,[["render",r]]);export{k as __pageData,m as default};
